header {
  background-color: #0d1b2a;
  color: #ffffff;
  width: 100%;
  padding: 1rem 2rem;
  border-bottom: 4px solid #e67e22;
}

header h1 {
  font-size: 1.4rem;
  font-weight: 600;
  letter-spacing: 0.02em;
}

main {
  display: flex;
  justify-content: center;
  padding: 2rem 1rem;
  min-height: calc(100vh - 60px);
}

.panel {
  background: #ffffff;
  border-radius: 8px;
  box-shadow: 0 2px 12px rgba(0,0,0,0.10);
  padding: 2rem;
  width: 100%;
  max-width: 720px;
}

.panel h2 {
  font-size: 1.25rem;
  margin-bottom: 1.5rem;
  color: #0d1b2a;
}

.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem 1.5rem;
}

@media (max-width: 560px) {
  .form-grid {
    grid-template-columns: 1fr;
  }
}

.field {
  display: flex;
  flex-direction: column;
  margin-bottom: 0.25rem;
}

.field.full {
  grid-column: 1 / -1;
}

label {
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: 0.25rem;
  color: #2c3e50;
}

input[type="text"],
input[type="email"],
input[type="date"],
input[type="password"] {
  width: 100%;
  padding: 0.5rem 0.75rem;
  border: 1px solid #b0bec5;
  border-radius: 4px;
  font-size: 1rem;
  color: #1a1a2e;
  background: #fafbfc;
  transition: border-color 0.15s ease;
}

input:focus {
  outline: 2px solid #e67e22;
  outline-offset: 1px;
  border-color: #e67e22;
  box-shadow: 0 0 0 2px rgba(230,126,34,0.2);
}

input[aria-invalid="true"] {
  border-color: #c0392b;
  background: #fdf0ef;
}

.error-msg {
  font-size: 0.8rem;
  color: #c0392b;
  min-height: 1.1em;
  margin-top: 0.15rem;
}

.password-wrapper {
  position: relative;
}

.password-wrapper input {
  padding-right: 2.8rem;
}

.toggle-pw {
  position: absolute;
  right: 0.4rem;
  top: 50%;
  transform: translateY(-50%);
  background: none;
  border: none;
  cursor: pointer;
  font-size: 0.8rem;
  color: #e67e22;
  font-weight: 600;
  padding: 0.2rem 0.4rem;
  border-radius: 3px;
}

.toggle-pw:hover, .toggle-pw:focus {
  background: rgba(230,126,34,0.1);
  outline: none;
}

.checkbox-field {
  display: flex;
  align-items: flex-start;
  gap: 0.5rem;
  margin-top: 0.5rem;
}

.checkbox-field input[type="checkbox"] {
  margin-top: 0.2rem;
  width: 1.1rem;
  height: 1.1rem;
  accent-color: #e67e22;
}

.checkbox-field label {
  font-weight: 400;
  font-size: 0.875rem;
  margin-bottom: 0;
}

.actions {
  margin-top: 1.5rem;
  display: flex;
  justify-content: flex-end;
}

.btn-submit {
  background-color: #e67e22;
  color: #ffffff;
  border: none;
  padding: 0.65rem 2rem;
  font-size: 1rem;
  font-weight: 600;
  border-radius: 4px;
  cursor: pointer;
  transition: background-color 0.15s ease;
}

.btn-submit:hover {
  background-color: #cf6d17;
}

.btn-submit:focus {
  outline: 2px solid #0d1b2a;
  outline-offset: 2px;
}

.success-banner {
  background: #d4edda;
  color: #155724;
  border: 1px solid #c3e6cb;
  border-radius: 4px;
  padding: 1rem;
  margin-bottom: 1rem;
  display: none;
  text-align: center;
  font-weight: 600;
}

.alert-summary {
  background: #fdf0ef;
  color: #c0392b;
  border: 1px solid #c0392b;
  border-radius: 4px;
  padding: 0.75rem 1rem;
  margin-bottom: 1rem;
  display: none;
  font-weight: 600;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
